import sys
from collections import defaultdict

def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    n = int(data[0].strip())
    dictionary = []
    for i in range(1, 1 + n):
        word = data[i].strip()
        if word:
            dictionary.append(word)

    # Build word pattern index: {word_length: {pattern: [words]}}
    word_pattern_index = defaultdict(lambda: defaultdict(list))
    for word in dictionary:
        pattern = []
        char_map = {}
        next_id = 0
        for ch in word:
            if ch not in char_map:
                char_map[ch] = next_id
                next_id += 1
            pattern.append(char_map[ch])
        pattern_tuple = tuple(pattern)
        word_pattern_index[len(word)][pattern_tuple].append(word)

    # Build reverse index for mapping validation
    words_by_length = defaultdict(list)
    for word in dictionary:
        words_by_length[len(word)].append(word)

    # Process encrypted lines
    for line in data[1 + n:]:
        line = line.rstrip('\n\r')
        if not line:
            print()
            continue

        result = decrypt_line(line, dictionary, word_pattern_index, words_by_length)
        print(result)

def get_pattern(s):
    """Get the canonical pattern of a string where repeated characters get the same number."""
    char_map = {}
    next_id = 0
    result = []
    for ch in s:
        if ch not in char_map:
            char_map[ch] = next_id
            next_id += 1
        result.append(char_map[ch])
    return tuple(result)

def decrypt_line(line, dictionary, word_pattern_index, words_by_length):
    words = line.split(' ')

    # Try to find a valid mapping using backtracking
    def solve(word_idx, forward_map, reverse_map):
        if word_idx == len(words):
            return forward_map

        encrypted_word = words[word_idx]
        candidates = word_pattern_index[len(encrypted_word)].get(get_pattern(encrypted_word), [])

        for candidate in candidates:
            new_forward = forward_map.copy()
            new_reverse = reverse_map.copy()
            valid = True

            for e, c in zip(encrypted_word, candidate):
                if e in new_forward:
                    if new_forward[e] != c:
                        valid = False
                        break
                else:
                    if c in new_reverse:
                        valid = False
                        break
                    new_forward[e] = c
                    new_reverse[c] = e

            if valid:
                result = solve(word_idx + 1, new_forward, new_reverse)
                if result is not None:
                    return result

        return None

    mapping = solve(0, {}, {})

    if mapping is None:
        # No solution found - replace all letters with *
        result_words = []
        for word in words:
            result_word = ''.join('*' if ch.isalpha() else ch for ch in word)
            result_words.append(result_word)
        return ' '.join(result_words)
    else:
        # Apply the mapping
        result_words = []
        for word in words:
            result_word = ''.join(mapping.get(ch, '*') for ch in word)
            result_words.append(result_word)
        return ' '.join(result_words)

if __name__ == "__main__":
    main()
